import{z as r,x as s,o as t,c as A,q as E,j as n,D as e,d as o,s as l,S as d}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Token 嵌入查找","description":"","frontmatter":{"title":"Token 嵌入查找","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/embedding-lookup.md","filePath":"llm/embedding-lookup.md","lastUpdated":1791063341000}'),p={name:"llm/embedding-lookup.md"};function m(h,a,B,_,b,D){const i=s("Mermaid");return t(),A("div",null,[a[2]||(a[2]=E('<h1 id="token-嵌入查找" tabindex="-1">Token 嵌入查找 <a class="header-anchor" href="#token-嵌入查找" aria-label="Permalink to &quot;Token 嵌入查找&quot;">​</a></h1><div class="epigraph"><p>我们用可学习的嵌入把输入符号与输出符号映成维度为 $d_{\\mathrm{model}}$ 的向量，这是后续各层共享的宽度。</p><footer>—— 据 Vaswani et al., Attention Is All You Need, NeurIPS 2017 整理</footer></div><p><a href="/llm/detokenize-roundtrip">上一课</a>把 id 序列与字符串的往返协议钉死。本课不重讲切分、UNK 或空格元符号。缺口是：编号仍是离散的，网络的加减与非线性需要 \\(\\mathbb{R}^{d}\\) 里的向量。方法是一张查找表 \\(E\\)，把每个 token 映成一行：\\(e_t=E[t]\\in\\mathbb{R}^{d}\\)。这是「嵌入」单元的第一课；是否与输出层共享、表有多大，是后两课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/token-as-discrete-unit">离散符号与词表</a>给出的对象是 \\(t\\in V\\) 的整数。整数不能直接进入矩阵乘：编号的算术没有意义，相邻 id 不必相邻。若把 id 当成标量特征来用，模型会以为 17 比 16「大一点」。正确的接口是无度量的查找：每个编号对应一条独立的向量，向量之间的几何完全由训练决定。</p><p><span class="marginnote">直觉类比：把 \\(E\\) 想成酒店的房号—房客名册。1701 号房和 1702 号房的住户毫无关系，房号的加减也不携带任何信息；「查表」就是按号找人。模型看到的只是被点到的那个人，号与号之间的秩序对它不可见。</span></p><p>查找表把离散问题变成「选一行」。选中的行成为该位置上残差流的初始内容（位置编码若存在，会加在这之上，那是后面位置课序的事）。没有这张表，后面的块没有可写的总线起点。本课只定义这一次查表，不定义层与层之间如何改写向量。</p><h3 id="查找不是-one-hot-矩阵乘的实现细节" tabindex="-1">查找不是 one-hot 矩阵乘的实现细节 <a class="header-anchor" href="#查找不是-one-hot-矩阵乘的实现细节" aria-label="Permalink to &quot;查找不是 one-hot 矩阵乘的实现细节&quot;">​</a></h3><p>代数上 \\(e_t\\) 等于 one-hot 向量乘 \\(E\\)。实现上从不物化 \\(|V|\\) 维稀疏向量，而是一次 gather：用整数下标从连续内存里取出 \\(d\\) 个数。梯度同样是 scatter：只更新被点到的行。把嵌入理解成「第一层线性」在数学上没错，在工程上会误导人去走稠密 GEMM、去给未出现的行分配计算。它是查表。</p><p><span class="marginnote">\\(d\\) 在本课只是嵌入行的宽度。它稍后会等于残差流宽度 \\(d_{\\mathrm{model}}\\)，那是为了让相加合法。本课不讨论为什么取 4096 而不是 512，那是 <a href="/llm/embedding-dmodel">词表宽度与 d_model</a> 的账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(E\\in\\mathbb{R}^{|V|\\times d}\\)，第 \\(t\\) 行记为 \\(E_t\\)。一批序列 \\(T\\in\\{0,\\ldots,|V|-1\\}^{B\\times n}\\) 经过查找得到 \\(X\\in\\mathbb{R}^{B\\times n\\times d}\\)，其中 \\(X_{b,i}=E_{T_{b,i}}\\)。padding 位置仍会查出一个向量，通常紧接着被掩码乘零，或根本不参与后续注意力的键值。特殊符号各有自己的行：EOS 的向量会学成「这里该停」，PAD 的行往往接近任意，因为掩码挡掉了它的影响。</p><p><span class="marginnote">初学者容易以为 PAD 行也会「学到东西」；实际上掩码把它的影响挡死了，PAD 行基本停在初始化附近。它占着一整行参数，唯一的用处是让长短不一的序列能拼成矩形批量——所以掩码一步都不能省。</span></p><p>初始化常用较小的高斯或按 \\(1/\\sqrt{d}\\) 缩放，避免初始向量过大、把后面的层归一化推到奇怪的尺度。训练目标通过后续层的反传到达被点中的行。一个 token 若在语料里几乎不出现，它的行停留在初始化附近——这与上一单元「长尾行学不透」是同一现象，只是现在能指到具体的矩阵行。</p><p><span class="marginnote">数字实例：batch 为 \\(8\\times2048\\) 时共 16384 个位置，即便 id 互不相同，也只点到 128k 词表的约一成多；重复 token 还要再打折扣。所以「一步只更新一小部分行」不是修辞——大部分行在这一步完全没有梯度。</span></p>',15)),(t(),n(d,null,{default:e(()=>[l(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E4%B8%80%E4%B8%AA%20batch%20%E7%9A%84%20id%20%E5%BA%8F%E5%88%97%22%5D%20--%3E%20LUT%5B%22gather%20%E5%8F%96%E8%A1%8C%22%5D%0A%20%20LUT%20--%3E%20FWD%5B%22%E5%89%8D%E5%90%91%E4%B8%8E%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20FWD%20--%3E%20BWD%5B%22%E5%8F%8D%E5%90%91%E7%AE%97%E5%87%BA%E5%90%84%E4%BD%8D%E7%BD%AE%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20BWD%20--%3E%20SCT%5B%22scatter%3A%20%E6%A2%AF%E5%BA%A6%E5%8A%A0%E5%9B%9E%E8%A2%AB%E7%82%B9%E5%88%B0%E7%9A%84%E8%A1%8C%22%5D%0A%20%20SCT%20--%3E%20HOT%5B%22%E9%AB%98%E9%A2%91%E8%A1%8C%3A%20%E5%8F%8D%E5%A4%8D%E6%9B%B4%E6%96%B0%22%5D%0A%20%20SCT%20--%3E%20COLD%5B%22%E9%95%BF%E5%B0%BE%E8%A1%8C%3A%20%E5%81%9C%E5%9C%A8%E5%88%9D%E5%A7%8B%E5%8C%96%E9%99%84%E8%BF%91%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="位置上的加法尚未发生" tabindex="-1">位置上的加法尚未发生 <a class="header-anchor" href="#位置上的加法尚未发生" aria-label="Permalink to &quot;位置上的加法尚未发生&quot;">​</a></h3><p>本课的输出是「每个位置一个内容向量」。绝对位置嵌入会再查另一张长度为上下文上限的表，与 \\(X\\) 相加；旋转位置则在注意力里改写查询键的相位。那些都还没发生。先保证内容查找本身是 gather，再谈位置，否则会把 \\(E\\) 和位置表揉成一张说不清的「输入矩阵」。</p><p><span class="marginnote">共享词表的多语言系统里，同一行可能被许多语言点到，几何是混用的。这不是 bug，是容量分配：高频语言会主导这些行的更新方向。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>查找把监督信号按符号身份分开。梯度 \\(\\partial L/\\partial E_t\\) 只含那些 \\(t\\) 出现过的位置的贡献。这造成自然的频次加权：常见 token 的行被反复拉向有用的方向，罕见行噪声大。子词切分的一个作用，就是让罕见词形去点那些更新更勤的短符号行，而不是去点一条几乎不动的整词行。</p><p>因为行与行之间在表内没有耦合（除非后面用 tying、因式分解或自适应输入把表结构改掉），嵌入几何完全由它们在后续块里被如何读写来塑造。两行可以学成几乎平行，也可以学成正交。id 相近不提供归纳偏置。任何「相似词应靠近」都是损失与数据的结果，不是查找表的结构。</p><h3 id="批量与稀疏更新" tabindex="-1">批量与稀疏更新 <a class="header-anchor" href="#批量与稀疏更新" aria-label="Permalink to &quot;批量与稀疏更新&quot;">​</a></h3><p>大词表时，\\(E\\) 往往是模型里第一块连续的大矩阵，但一步训练只碰其中很小的行子集。优化器若为每一行维护动量与二阶统计，内存会按 \\(|V|\\times d\\) 再乘系数。实现可以选择对嵌入用更简单的优化器状态，或把表分片到多卡上按 id 路由。这些是内存课会再碰到的点；机制上只需记住：计算是稀疏的，存储是稠密的。</p><p><span class="marginnote">不要在查表前把 id 归一化或嵌入成浮点特征。任何对编号的光滑函数都会把任意的编号秩序注入模型。离散身份只能通过下标使用。</span></p>',9)),(t(),n(d,null,{default:e(()=>[l(i,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22token%20id%20%E5%BA%8F%E5%88%97%22%5D%20--%3E%20GATH%5B%22%E6%8C%89%E8%A1%8C%20gather%22%5D%0A%20%20E%5B%22%E6%9F%A5%E6%89%BE%E8%A1%A8%20E%20%E5%B1%9E%E4%BA%8E%20R%20%E4%B8%8A%20%7CV%7C%20%E4%B9%98%20d%22%5D%20--%3E%20GATH%0A%20%20GATH%20--%3E%20X%5B%22%E4%BD%8D%E7%BD%AE%E4%B8%8A%E7%9A%84%E5%90%91%E9%87%8F%20X%22%5D%0A%20%20X%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%98%AF%E5%90%A6%E4%B8%8E%E8%BE%93%E5%87%BA%E5%85%B1%E4%BA%AB%E3%80%81%E5%AE%BD%E5%BA%A6%E5%A6%82%E4%BD%95%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>查找表假定 id 在 \\(0\\ldots|V|-1\\) 内。越界是实现错误，不是 UNK：UNK 是合法编号，越界是协议被破坏。冻结嵌入、只训练后面的层，在领域适应里常见，等于声明「符号几何已经够用」。多模态里视觉切片也走查找或线性投影，但视觉侧通常不是一张 \\(|V|\\) 行的离散表，而是补丁的线性映射；不要把两者叫成同一个算子。</p><p>本课之后，默认「输入已经是 \\(X\\in\\mathbb{R}^{n\\times d}\\)」。下一课问这张 \\(E\\) 要不要与分类头共用；再下一课把 \\(|V|\\) 与 \\(d\\) 的乘积写成内存预算。不在本课展开残差或注意力。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离散 id 通过查找表 \\(E\\in\\mathbb{R}^{|V|\\times d}\\) 变成向量 \\(E[t]\\)，实现是 gather 不是稠密乘。</li><li>编号无度量；行与行的几何完全由训练决定。</li><li>梯度只更新被点到的行，故长尾行学不透、短符号行更新勤。</li><li>位置编码尚未加入；本课只提供内容向量。</li><li>后续块默认输入已是宽为 \\(d\\) 的序列。</li><li>出处：Vaswani et al., NeurIPS 2017（学习嵌入作为 \\(d_{\\mathrm{model}}\\) 宽度的入口）。</li></ul>',5))])}const T=r(p,[["render",m]]);export{u as __pageData,T as default};
